@extends('layouts.admin') @section('title',$purchaseOrder->po_number) @section('page-title','Purchase Order') @section('content')<div class="ad-page-head"><div><a class="ad-back" href="{{ route('admin.purchase-orders.index') }}">← Purchase orders</a><h2>{{ $purchaseOrder->po_number }}</h2><p>{{ $purchaseOrder->supplier->name }} → {{ $purchaseOrder->warehouse->name }}</p></div>@if(!in_array($purchaseOrder->status,['received','cancelled']))<form method="POST" action="{{ route('admin.purchase-orders.receive',$purchaseOrder) }}" onsubmit="return confirm('Receive all remaining items into inventory?')">@csrf<button class="btn btn-primary">Receive all stock</button></form>@endif</div><div class="row g-4"><div class="col-lg-8"><div class="card p-4"><div class="table-responsive"><table class="table"><thead><tr><th>Product</th><th>Ordered</th><th>Received</th><th>Cost</th><th>Total</th></tr></thead><tbody>@foreach($purchaseOrder->items as $i)<tr><td>{{ $i->product->name }}<small class="d-block text-muted">{{ $i->variation?->attribute_value }}</small></td><td>{{ $i->quantity }}</td><td>{{ $i->received_quantity }}</td><td>{{ number_format($i->cost,2) }}</td><td>{{ number_format($i->total,2) }}</td></tr>@endforeach</tbody></table></div></div></div><div class="col-lg-4"><div class="card p-4 ad-sticky-card"><span class="ad-status is-{{ $purchaseOrder->status }} mb-3">{{ $purchaseOrder->status }}</span><div class="ad-mini-metric"><span>Subtotal</span><strong>{{ number_format($purchaseOrder->subtotal,2) }}</strong></div><div class="ad-mini-metric"><span>Total</span><strong>{{ number_format($purchaseOrder->total,2) }}</strong></div><div class="ad-mini-metric"><span>Expected</span><strong>{{ $purchaseOrder->expected_at?->format('d M Y')?:'—' }}</strong></div>@if(!in_array($purchaseOrder->status,['received','cancelled']))<form method="POST" action="{{ route('admin.purchase-orders.status',$purchaseOrder) }}" class="mt-3">@csrf @method('PUT')<select class="form-select mb-2" name="status"